package cn.lambdalib.util.datapart;
import java.util.*; public class EntityData {private static Map<Object,EntityData> data=new IdentityHashMap<>(); public static EntityData get(Object entity){return data.computeIfAbsent(entity,e->new EntityData(e));} private final Object entity; private Map<Class<?>,Object> parts=new HashMap<>(); private EntityData(Object e){entity=e;} public <T> T getPart(Class<T> c){return c.cast(parts.computeIfAbsent(c,k->{try{Object p=k.getConstructor().newInstance(); ((DataPart)p).entity=entity; return p;}catch(Exception e){throw new RuntimeException(e);}}));} }
